package com.vit.archds.service;
import com.fasterxml.jackson.databind.*; import com.vit.archds.entity.*; import com.vit.archds.repository.*; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient; import java.util.*;
@Service
public class AnalysisWorker {
 private final AnalysisJobRepository jobs;private final ProjectService projects;private final RequirementRepository reqs;private final ArchitectureCandidateRepository candidates;private final OptimizationResultRepository optimizations;private final VerificationResultRepository verifications;private final RefinementIterationRepository refinements;private final ExplanationRepository explanations;private final ArchitectureDiagramRepository diagrams;private final AuditLogRepository audit;private final RestClient ai;private final ObjectMapper mapper;
 public AnalysisWorker(AnalysisJobRepository j,ProjectService p,RequirementRepository r,ArchitectureCandidateRepository c,OptimizationResultRepository o,VerificationResultRepository v,RefinementIterationRepository ri,ExplanationRepository e,ArchitectureDiagramRepository d,AuditLogRepository a,RestClient ai,ObjectMapper m){jobs=j;projects=p;reqs=r;candidates=c;optimizations=o;verifications=v;refinements=ri;explanations=e;diagrams=d;audit=a;this.ai=ai;mapper=m;}
 @Async("analysisExecutor") public void runAsync(long id){AnalysisJob j=jobs.findById(id).orElse(null);if(j==null)return;try{j.start();stage(j,"REQUIREMENT_ANALYSIS",10,"Requirement Analysis Agent is extracting architectural drivers");Requirement r=reqs.findTopByProjectOrderByCreatedAtDesc(j.getProject()).orElseThrow();Map<String,Object> body=new LinkedHashMap<>();body.put("project_name",j.getProject().getName());body.put("description",j.getProject().getDescription());body.put("functional_requirements",split(r.getFunctionalRequirements()));body.put("non_functional_requirements",split(r.getNonFunctionalRequirements()));body.put("constraints",split(r.getConstraints()));body.put("technology_preferences",split(r.getTechnologyPreferences()));body.put("expected_users",r.getExpectedUsers());body.put("budget",r.getBudget());Map<String,Integer> customWeights=mapper.readValue(r.getQualityWeightsJson(),Map.class);if(customWeights!=null&&!customWeights.isEmpty())body.put("quality_weights",customWeights);body.put("num_alternatives",Math.max(2,Math.min(8,Optional.ofNullable(r.getAlternatives()).orElse(5))));body.put("max_iterations",Math.max(1,Math.min(10,Optional.ofNullable(r.getMaxIterations()).orElse(5))));stage(j,"AI_PIPELINE",20,"Executing the 20-agent architecture tournament, adversarial review and optimization workflow");String response=null; Exception lastAiError=null; for(int attempt=1;attempt<=4;attempt++){try{response=ai.post().uri("/api/v1/pipeline").body(body).retrieve().body(String.class); if(response!=null&&!response.isBlank()) break;}catch(Exception ex){lastAiError=ex; if(attempt<4) try{Thread.sleep(1500L*attempt);}catch(InterruptedException ie){Thread.currentThread().interrupt(); throw new IllegalStateException("Analysis interrupted while waiting for AI service",ie);}}} if(response==null||response.isBlank()){if(lastAiError!=null) throw new IllegalStateException("AI service unavailable at http://localhost:8000. Start scripts\\start-ai.cmd and retry. Root cause: "+safeMessage(lastAiError),lastAiError); throw new IllegalStateException("AI service returned an empty response");}j.setPipelineResponseJson(response);stage(j,"PERSISTING_RESULTS",90,"Persisting structured candidates, optimization, verification, diagrams and audit artifacts");persistAll(j,mapper.readTree(response));j.complete();jobs.save(j);audit.save(new AuditLog(j.getProject().getOwner(),"ANALYSIS_COMPLETED","JOB",j.getJobId()));}catch(Exception e){String detail=safeMessage(e);System.err.println("[ARCHDS] Analysis job "+j.getJobId()+" failed: "+detail);e.printStackTrace();j.fail(detail);jobs.save(j);try{audit.save(new AuditLog(j.getProject().getOwner(),"ANALYSIS_FAILED","JOB",j.getJobId()));}catch(Exception auditError){System.err.println("[ARCHDS] Could not persist failure audit: "+auditError.getMessage());}}}
 private void stage(AnalysisJob j,String s,int p,String m){j.update(s,p,m);jobs.save(j);}
 private void persistAll(AnalysisJob job,JsonNode root){Map<String,ArchitectureCandidate> map=new LinkedHashMap<>();JsonNode cs=root.path("candidates");if(cs.isArray())for(JsonNode c:cs){ArchitectureCandidate x=new ArchitectureCandidate(job,c.path("candidate_id").asText(UUID.randomUUID().toString()),c.path("name").asText("Architecture Candidate"),c.path("pattern_key").asText("adaptive"));x.setDescription(c.path("description").asText());x.setComponentsJson(c.path("components").toString());x.setRelationsJson(c.path("relations").toString());x.setTechnologiesJson(c.path("tech_stack").toString());x.setAdvantagesJson(c.path("advantages").toString());x.setDisadvantagesJson(c.path("disadvantages").toString());x.setAssumptionsJson(c.path("assumptions").toString());x.setRisksJson(c.path("risks").toString());x.setScoresJson(c.path("scores").toString());x.setWeightedScore(c.path("scores").path("weighted_total").asDouble());x.setParetoOptimal(c.path("is_pareto_optimal").asBoolean(false));x.setVerified(c.path("verified").asBoolean(false));x.setRefinementIteration(c.path("refinement_iteration").asInt(0));x.setPlantUmlSource(c.path("plantuml_source").asText(""));x.setDiagramSvg(c.path("diagram_svg").asText(""));ArchitectureCandidate saved=candidates.save(x);map.put(saved.getCandidateKey(),saved);verifications.save(new VerificationResult(saved,saved.getVerified(),c.path("verification_issues").toString(),c.path("requirement_coverage").toString()));if(saved.getPlantUmlSource()!=null&&!saved.getPlantUmlSource().isBlank())diagrams.save(new ArchitectureDiagram(saved,saved.getPlantUmlSource(),saved.getDiagramSvg()));}
 JsonNode opt=root.path("optimization");optimizations.save(new OptimizationResult(job,opt.path("algorithm").asText("NSGA-II"),opt.path("objectives").toString(),opt.path("pareto_candidate_ids").toString(),opt.path("tradeoffs").toString()));for(JsonNode it:root.path("refinement_history"))refinements.save(new RefinementIteration(job,it.path("iteration").asInt(),it.path("action").asText(),it.toString()));for(JsonNode ex:root.path("explanations")){ArchitectureCandidate c=map.get(ex.path("candidate_id").asText());if(c!=null)explanations.save(new Explanation(c,ex.path("rationale").asText(),ex.path("strengths").toString(),ex.path("tradeoffs").toString(),ex.path("risks").toString(),ex.path("assumptions").toString(),ex.path("confidence").asDouble(),ex.path("change_factors").toString()));}
 }
 private List<String> split(String value){
     if(value==null||value.isBlank()) return List.of();
     return Arrays.stream(value.split("\\R|;")).map(String::trim).filter(v->!v.isBlank()).toList();
 }
 private String safeMessage(Exception e){
     Throwable root=e;
     while(root.getCause()!=null && root.getCause()!=root) root=root.getCause();
     String m=root.getMessage();
     if(m==null||m.isBlank()) m=e.getMessage();
     if(m==null||m.isBlank()) return e.getClass().getSimpleName();
     return m.length()>1800?m.substring(0,1800):m;
 }
}

